INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','modal-deduction','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"modal-deduction","title":"Deductions and degrees of certainty","level":"B2","order":40,"summary":"Express conclusions and possibilities without confusing certainty with obligation.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["A strong positive conclusion","A strong negative conclusion","An uncertain possibility","Match the verb form to the time"],"rules":[{"title":"A strong positive conclusion","explanation":"Must can express a strong deduction based on evidence. This differs from must as an obligation. Must be working means the speaker concludes that the activity is happening; it does not necessarily order anyone to work.","pattern":"The lights are on; someone **must be working**.","commonMistakes":["A deduction is the speaker’s judgement, not an absolute guarantee."],"examples":["You draw a strong positive conclusion from clear evidence: “They **must** be preparing the visitor guide.”","You draw a strong positive conclusion from clear evidence: “They **must** be restoring the old portrait.”"],"skill":"form"},{"title":"A strong negative conclusion","explanation":"Can’t and cannot can express that something is impossible according to the available evidence. Mustn’t normally expresses prohibition rather than the ordinary negative counterpart of deductive must.","pattern":"That **can’t be** the right address.","commonMistakes":["Do not substitute mustn’t when you mean that something is impossible."],"examples":["The evidence rules this out as impossible: “They **cannot** be preparing the visitor guide.”","The evidence rules this out as impossible: “They **cannot** be restoring the old portrait.”"],"skill":"meaning"},{"title":"An uncertain possibility","explanation":"May, might and could often express an uncertain possibility. Their relative strength depends on context, intonation and variety, so these exercises do not assign fixed percentage probabilities. A negative may not or might not means possibly not.","pattern":"She **might be** at home.","commonMistakes":["Could not often suggests impossibility; it is not always interchangeable with might not."],"examples":["The evidence is inconclusive; this is only possible: “They **might** be preparing the visitor guide.”","The evidence is inconclusive; this is only possible: “They **might** be restoring the old portrait.”"],"skill":"contrast"},{"title":"Match the verb form to the time","explanation":"For a present activity, use modal + be + -ing. For a state, use modal + base verb. Future probability can also use be likely to or probably. Keep probably before a negative modal in the common phrase probably won’t.","pattern":"They **must be waiting**. / They **are likely to arrive** soon.","commonMistakes":["A present deduction about an activity needs be before -ing; must waiting is incomplete."],"examples":["Build a deduction about an action happening now: “She must **be preparing** the visitor guide.”","Build a deduction about an action happening now: “She must **be restoring** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-deduction"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Express conclusions and possibilities without confusing certainty with obligation.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"A strong positive conclusion","explanation":"Must can express a strong deduction based on evidence. This differs from must as an obligation. Must be working means the speaker concludes that the activity is happening; it does not necessarily order anyone to work.","pattern":"The lights are on; someone **must be working**.","commonMistakes":["A deduction is the speaker’s judgement, not an absolute guarantee."],"examples":["You draw a strong positive conclusion from clear evidence: “They **must** be preparing the visitor guide.”","You draw a strong positive conclusion from clear evidence: “They **must** be restoring the old portrait.”"],"skill":"form","id":"modal-deduction-foundation-1","domain":"verbs","referenceIds":["bc-deduction"],"readingVersion":"core-2026-09-v3"},{"title":"A strong negative conclusion","explanation":"Can’t and cannot can express that something is impossible according to the available evidence. Mustn’t normally expresses prohibition rather than the ordinary negative counterpart of deductive must.","pattern":"That **can’t be** the right address.","commonMistakes":["Do not substitute mustn’t when you mean that something is impossible."],"examples":["The evidence rules this out as impossible: “They **cannot** be preparing the visitor guide.”","The evidence rules this out as impossible: “They **cannot** be restoring the old portrait.”"],"skill":"meaning","id":"modal-deduction-foundation-2","domain":"verbs","referenceIds":["bc-deduction"],"readingVersion":"core-2026-09-v3"},{"title":"An uncertain possibility","explanation":"May, might and could often express an uncertain possibility. Their relative strength depends on context, intonation and variety, so these exercises do not assign fixed percentage probabilities. A negative may not or might not means possibly not.","pattern":"She **might be** at home.","commonMistakes":["Could not often suggests impossibility; it is not always interchangeable with might not."],"examples":["The evidence is inconclusive; this is only possible: “They **might** be preparing the visitor guide.”","The evidence is inconclusive; this is only possible: “They **might** be restoring the old portrait.”"],"skill":"contrast","id":"modal-deduction-foundation-3","domain":"verbs","referenceIds":["bc-deduction"],"readingVersion":"core-2026-09-v3"},{"title":"Match the verb form to the time","explanation":"For a present activity, use modal + be + -ing. For a state, use modal + base verb. Future probability can also use be likely to or probably. Keep probably before a negative modal in the common phrase probably won’t.","pattern":"They **must be waiting**. / They **are likely to arrive** soon.","commonMistakes":["A present deduction about an activity needs be before -ing; must waiting is incomplete."],"examples":["Build a deduction about an action happening now: “She must **be preparing** the visitor guide.”","Build a deduction about an action happening now: “She must **be restoring** the old portrait.”"],"skill":"application","id":"modal-deduction-foundation-4","domain":"verbs","referenceIds":["bc-deduction"],"readingVersion":"core-2026-09-v3"},{"domain":"verbs","id":"modal-ambiguity-and-strength","title":"Possibility, deduction, permission and ability","explanation":"Can, could, may and might do different jobs in different contexts. A general possibility differs from a tentative judgement about one situation. Must can express an obligation or a strong inference. Should can express advice or an expectation. Identify whether the speaker is reasoning about reality or regulating an action.","pattern":"You **must be tired** / You **must wear a helmet**","examples":["It **can be cold** here in spring.","She **may be at home** now."],"commonMistakes":["Do not assign fixed numerical probabilities to may, might or could. Their strength depends on context, stress and the alternatives under discussion."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["The lights are on; someone **must be working**.","That **can’t be** the right address.","She **might be** at home.","They **must be waiting**. / They **are likely to arrive** soon."],"readingVersion":"core-2026-09-v4"},"stage":"4 · Connecting meanings","prerequisites":["modal-obligation"],"readingReferenceIds":["bc-deduction","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='modal-deduction'
